import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { teamLogic } from 'scenes/teamLogic'

import { TeamPublicType, TeamType } from '~/types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface hasIngestedEventLogicValues {
    currentTeam: TeamPublicType | TeamType | null // teamLogic
    realDataObservedThisSession: boolean
    hasIngestedEvent: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface hasIngestedEventLogicActions {
    loadCurrentTeam: () => any // teamLogic
    reportRealDataObserved: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface hasIngestedEventLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        hasIngestedEvent: (
            currentTeam: TeamPublicType | TeamType | null,
            realDataObservedThisSession: boolean
        ) => boolean
    }
}

export type hasIngestedEventLogicType = MakeLogicType<
    hasIngestedEventLogicValues,
    hasIngestedEventLogicActions,
    Record<string, any>,
    hasIngestedEventLogicMeta
>

/**
 * Single source of truth for "has this project ever seen a real event", reconciled against what's
 * actually on screen. `currentTeam.ingested_event` is flipped server-side by the ingestion service
 * and only reaches the frontend on the next team refresh, so it can lag well behind a scene that's
 * already rendering real data (live events, query results, etc). Any such scene should call
 * `reportRealDataObserved` — this both unblocks banners/redirects gated on the flag for the rest of
 * the session and kicks an immediate team refresh so the flag itself catches up.
 */
export const hasIngestedEventLogic = kea<hasIngestedEventLogicType>([
    path(['lib', 'logic', 'hasIngestedEventLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeam']],
        actions: [teamLogic, ['loadCurrentTeam']],
    })),
    actions({
        reportRealDataObserved: true,
    }),
    reducers({
        realDataObservedThisSession: [
            false,
            {
                reportRealDataObserved: () => true,
            },
        ],
    }),
    selectors({
        hasIngestedEvent: [
            (s) => [s.currentTeam, s.realDataObservedThisSession],
            (currentTeam, realDataObservedThisSession): boolean =>
                !!currentTeam?.ingested_event || realDataObservedThisSession,
        ],
    }),
    listeners(({ actions, values }) => ({
        reportRealDataObserved: () => {
            if (values.currentTeam && !values.currentTeam.ingested_event) {
                actions.loadCurrentTeam()
            }
        },
    })),
])
